"""Paper abstract and selected figures with bilingual presentation."""

import json
from pathlib import Path

from paper_source import render_excerpt


def bi(zh: str, en: str) -> str:
    return f'<span data-language="zh">{zh}</span><span data-language="en">{en}</span>'


def render() -> str:
    data = json.loads((Path(__file__).resolve().parent / "assets/paper-data.json").read_text(encoding="utf-8"))
    # English is taken verbatim from main.tex; only TeX markup/cross-references are rendered.
    abstract = bi(render_excerpt("abstract", "zh"), render_excerpt("abstract", "en"))
    page = f'''<main class="paper-content">
<header class="paper-header"><div class="eyebrow">{bi("研究论文 · HTML 交互版", "Research paper · interactive HTML")}</div><h1>RoTA-Bench</h1><p class="paper-title">{bi("通过交互式投影对齐评估三维空间推理", "Evaluating 3D Spatial Reasoning through Interactive Projection Alignment")}</p><div class="author-list">Qingchuan Ma<sup>1</sup>, Yuexiao Ma<sup>2</sup>, Xiang Meng<sup>1</sup>, Yixuan Zou<sup>1</sup>, Tianyu Xie<sup>1</sup>, Wang Chen<sup>1</sup>, Yuhui Zeng<sup>1</sup>, Yuhang Wu<sup>1</sup>, Xiawu Zheng<sup>1</sup>, Rongrong Ji<sup>1</sup><br><sup>1</sup> Xiamen University · <sup>2</sup> Nanyang Technological University</div></header>
<nav class="paper-toc">{bi("摘要　图示", "Abstract　Figures")}</nav>
<article class="paper-article">
<section class="paper-section" id="abstract"><h2>{bi("摘要", "Abstract")}</h2><div class="source-copy">{abstract}</div></section>
<section class="paper-section" id="figures"><h2>{bi("图示", "Figures")}</h2>
<figure class="paper-figure"><h3>{bi("RoTA-Bench 概览", "RoTA-Bench overview")}</h3><img src="/assets/rota-overview.png" alt="RoTA-Bench overview"><p class="figure-takeaway">{bi("结论：基准包含 674 个可解任务，并从中分层抽取 100 个测试任务；任务要求根据投影观察逐步旋转，直至 IoU 达到 0.90。", "Takeaway: The benchmark contains 674 solvable tasks and a stratified 100-task test set; agents rotate from visual observations until projection IoU reaches 0.90.")}</p><p class="metric-note">{bi("指标：IoU = 当前轮廓与目标轮廓的交并比；达到 0.90 判定任务成功。", "Measure: IoU is the intersection-over-union of current and target silhouettes; 0.90 marks task success.")}</p></figure>
<figure class="paper-figure"><h3>{bi("构建与评测流程", "Construction and evaluation pipeline")}</h3><img loading="lazy" src="/assets/rota-pipeline.png" alt="RoTA-Bench construction and evaluation pipeline"><p class="figure-takeaway">{bi("结论：流程由图标生成三维物体、搜索参考路径，再构建分层测试集，保证任务可达且评测可复现。", "Takeaway: The pipeline turns icons into 3D objects, searches reference paths, and builds a stratified test set for reachable, reproducible evaluation.")}</p><p class="metric-note">{bi("指标：参考路径长度是到达目标姿态所需的离散旋转步数；测试集按路径长度分层抽样。", "Measure: Reference-path length counts discrete rotations to the target pose; test tasks are stratified by this length.")}</p></figure>
<figure class="paper-figure"><h3>{bi("各方法的 IoU 随交互步数变化", "IoU over interaction steps")}</h3><div class="paper-controls"><label>{bi("突出显示方法", "Highlight a method")} <select id="series-focus"><option value="all">All methods</option></select></label><span>{bi("悬停数据点查看精确值；图例可筛选曲线。", "Hover over points for exact values; use the legend to filter curves.")}</span></div><div id="paper-legend" class="paper-legend"></div><svg id="paper-line-chart" class="linechart" viewBox="0 0 1200 440" role="img"></svg><p class="figure-takeaway">{bi("结论：人类平均 IoU 越过 0.90 成功线，模型曲线整体停留在较低水平。", "Takeaway: Human mean IoU crosses the 0.90 success threshold, while model trajectories plateau substantially lower.")}</p><p class="metric-note">{bi("指标：每步 IoU 为该步仍在运行任务的最终保留 IoU 的平均值；终止后延续至第 48 步。", "Measure: At each step, IoU is averaged across tasks, retaining terminal IoU after termination through step 48.")}</p><figcaption>{bi("固定 100 个测试任务在 0–48 步的平均 IoU。虚线为 0.90 成功阈值。", "Mean IoU over the fixed 100-task test set at steps 0–48. Dashed line: 0.90 success threshold.")}</figcaption></figure>
<figure class="paper-figure"><h3>{bi("100 个测试任务的主结果", "Main results on 100 test tasks")}</h3><p class="chart-help">{bi("点击表头排序。所有数值来自论文主结果表。", "Click a column heading to sort. Values are from the paper's main results table.")}</p><div class="table-wrap paper-results-wrap"><table id="paper-results" class="paper-table"><thead><tr>{''.join(f'<th><button type="button" data-sort="{i}"></button></th>' for i in range(9))}</tr></thead><tbody></tbody></table></div><p class="figure-takeaway">{bi("结论：人类在 100 个任务上全部成功；GPT-5.6-Sol 成功率为 17%，ReAct 的最终 IoU 最高（0.628）。", "Takeaway: Humans solve all 100 tasks; GPT-5.6-Sol succeeds on 17%, while ReAct has the highest final IoU (0.628).")}</p><p class="metric-note">{bi("指标：成功率 = IoU≥0.90 的任务比例；Final IoU 与步数对全部任务取均值；覆盖率 = 过程中至少观察到一次的物体表面积比例。有效方向率按至少存在一个可降低姿态误差的角度定义；Best angle、Gap、Loss 仅统计有效方向。", "Measures: Success rate is the fraction with IoU ≥ 0.90; Final IoU and steps are averaged over all tasks; coverage is the fraction of surface observed at least once. Effective direction requires some legal angle to reduce pose error; Best angle, Gap, and Loss are computed only for effective directions.")}</p><figcaption>{bi("按论文中的 Final IoU 降序排列；Cov. 为可视表面覆盖率。", "Sorted by Final IoU as in the paper; Cov. denotes visual surface coverage.")}</figcaption></figure>
<figure class="paper-figure"><h3>{bi("输入消融：辅助视图与交互历史", "Input ablation: auxiliary views and interaction history")}</h3><div class="paper-controls"><span>{bi("悬停查看精确值；点击表头排序。", "Hover for exact values; click headers to sort.")}</span></div><div class="table-wrap"><table id="ablation-table" class="paper-table"><thead></thead><tbody></tbody></table></div><p class="figure-takeaway">{bi("结论：移除交互历史后最终 IoU 降至 0.4822，30° 动作占比升至 96.76%，表明细粒度角度控制依赖历史反馈。", "Takeaway: Removing interaction history lowers final IoU to 0.4822 and raises 30° actions to 96.76%, indicating that fine-grained angle control depends on interaction history.")}</p><p class="metric-note">{bi("指标：成功率按 IoU≥0.90 计算；有效方向率按所选轴向存在可降低姿态误差的合法角度计算；四档角度列为各角度动作占比；ρ 为动作前 IoU 与旋转角度的 Spearman 相关，附 95% 置信区间。", "Measures: Success uses IoU ≥ 0.90; effective direction means the chosen axis has a legal angle that reduces pose error; angle columns are action shares; ρ is Spearman correlation between pre-action IoU and rotation magnitude, with 95% CI.")}</p><figcaption>{bi("GPT-5.6-Sol 在前 30 个测试任务上的结果，条件按 Final IoU 排序。", "GPT-5.6-Sol results on the first 30 test tasks, sorted by Final IoU.")}</figcaption></figure>
<figure class="paper-figure"><h3>{bi("旋转角度与投影 / 姿态差异的相关性", "Association of rotation angle with projection / pose discrepancy")}</h3><div class="paper-controls"><span>{bi("悬停柱条查看 |ρ| 与 95% bootstrap 区间；点击图例筛选。", "Hover over bars for |ρ| and 95% bootstrap intervals; click legend items to filter.")}</span></div><div id="correlation-legend" class="paper-legend"></div><svg id="correlation-chart" class="research-chart" viewBox="0 0 1100 650" role="img"></svg><p class="figure-takeaway">{bi("结论：人类动作角度同时关联投影 IoU 与三维姿态误差；多数模型与投影 IoU 的关联更强。", "Takeaway: Human rotation angles are associated with both projection IoU and 3D pose error; most models are more strongly associated with projection IoU.")}</p><p class="metric-note">{bi("指标：ρ 为动作前 IoU 或姿态误差与所选旋转角度的 Spearman 相关；柱高显示 |ρ|，误差线为映射到绝对值后的 95% bootstrap 区间。", "Measure: ρ is the Spearman correlation of pre-action IoU or pose error with selected angle; bars show |ρ| and whiskers show the 95% bootstrap interval mapped to absolute values.")}</p><figcaption>{bi("100 个测试任务的绝对 Spearman 相关系数；区间跨 0 时，绝对值下界映射为 0。", "Absolute Spearman correlations across 100 test tasks; intervals crossing zero have a mapped absolute lower bound of zero.")}</figcaption></figure>
<figure class="paper-figure"><h3>{bi("匹配状态下的投影与姿态变化", "Projection and pose changes at matched states")}</h3><div class="paper-controls"><span>{bi("悬停查看比例与定义；点击图例显示或隐藏状态。", "Hover for percentages and definitions; click legend items to show or hide states.")}</span></div><div id="state-legend" class="paper-legend"></div><svg id="state-chart" class="research-chart state-chart" viewBox="0 0 1000 250" role="img"></svg><div class="table-wrap"><table id="state-context-table" class="paper-table"></table></div><p class="figure-takeaway">{bi("结论：在相同姿态起点上，GPT-5.6-Sol 更常出现 IoU 上升但姿态误差也上升的情况（19.43% vs. 人类 10.90%）。", "Takeaway: From matched starting poses, GPT-5.6-Sol more often improves IoU while increasing pose error (19.43% vs. 10.90% for humans).")}</p><p class="metric-note">{bi("指标：211 对匹配状态中，每类动作占比按四种结果（IoU↑/↓ × 姿态误差↑/↓）统计；此前旋转步数、覆盖率在动作前计算，ΔIoU 与 −Δpose 为动作后的平均变化。", "Measures: Action shares across 211 matched states use the four IoU (up/down) × pose-error (up/down) outcomes; prior rotations and coverage are measured before action, while ΔIoU and −Δpose are mean post-action changes.")}</p><figcaption>{bi("Human 与 GPT-5.6-Sol 在 211 个完全匹配状态上的行动结果。", "Action outcomes for Human and GPT-5.6-Sol across 211 exactly matched states.")}</figcaption></figure>
</section>
</article><script>window.paperData={data!r};</script><script src="/assets/paper-interactive.js" defer></script><script src="/assets/paper-main-charts.js" defer></script></main><div id="paper-tooltip" class="chart-tooltip"></div>'''
    download = f'<a class="paper-download" href="/paper/download" download="RoTA-Bench.pdf">{bi("下载论文 PDF", "Download PDF")}</a>'
    return page.replace("</header>", download + "</header>", 1)
